INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 2, '{"stem": "爷爷今年63岁，小华今年7岁，爸爸的年龄是小华的5倍。爸爸今年多少岁？", "options": null}', '35岁', '求一个数的几倍是多少用乘法：7×5=35（岁）。答：爸爸今年35岁。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p086.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 3, '{"stem": "爷爷今年63岁，小华今年7岁，爸爸的年龄是小华的5倍。爷爷比爸爸大多少岁？", "options": null}', '28岁', '先算爸爸的年龄：7×5=35（岁）；再算爷爷比爸爸大：63-35=28（岁）。答：爷爷比爸爸大28岁。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p086.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1030, '数学', '三年级', '应用题', 2, '{"stem": "爷爷今年63岁，小华今年7岁，爸爸的年龄是小华的5倍。爷爷的年龄是小华的几倍？", "options": null}', '9', '求63是7的几倍用除法：63÷7=9。答：爷爷的年龄是小华的9倍。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p086.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1030, '数学', '三年级', '应用题', 2, '{"stem": "欢欢买了一大盒80元的水果，乐乐买了一小盒5元的水果。欢欢买水果付的钱是乐乐的几倍？", "options": null}', '16', '求80是5的几倍用除法：80÷5=16。答：欢欢付的钱是乐乐的16倍。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p086.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1026, '数学', '三年级', '应用题', 2, '{"stem": "体育活动时，老师将54个羽毛球平均分给三年级6个班，每班分到多少个羽毛球？", "options": null}', '9个', '把54个羽毛球平均分成6份：54÷6=9（个）。答：每班分到9个羽毛球。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p087.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1030, '数学', '三年级', '应用题', 3, '{"stem": "体育活动时，老师将54个羽毛球平均分给三年级6个班，每班还分到3个乒乓球。每班分到的羽毛球个数是乒乓球的几倍？", "options": null}', '3', '先算每班分到羽毛球：54÷6=9（个）；求9是3的几倍：9÷3=3。答：羽毛球个数是乒乓球的3倍。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p087.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 2, '{"stem": "科技节比赛，三年级参加纸飞机比赛的同学有6人，参加水火箭比赛的人数是参加纸飞机比赛的12倍。参加水火箭比赛的同学有多少人？", "options": null}', '72人', '求6的12倍是多少用乘法：6×12=72（人）。答：参加水火箭比赛的有72人。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p087.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1030, '数学', '三年级', '应用题', 2, '{"stem": "科技节比赛，三年级参加纸飞机比赛的同学有6人，参加回旋镖比赛的有30人。参加回旋镖比赛人数是参加纸飞机比赛的多少倍？", "options": null}', '5', '求30是6的几倍用除法：30÷6=5。答：参加回旋镖比赛人数是纸飞机比赛的5倍。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p087.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1030, '数学', '三年级', '应用题', 3, '{"stem": "湖边共种树865棵，每两棵柳树之间种了两棵梧桐树。柳树、梧桐各种了多少棵？", "options": null}', '柳树289棵，梧桐576棵', '柳树和梧桐树按“柳、梧、梧”3棵一组循环排列：865÷3=288（组）……1（棵），余下的1棵是柳树。柳树：288+1=289（棵），梧桐：288×2=576（棵）。答：柳树289棵，梧桐576棵。', 'paper', '["practice", "ykl3sx", "4.9"]', '["paper_png/ykl3_sx/p087.png"]', 0);
